'use server'

import { cookies } from 'next/headers'
import { revalidatePath } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'on'

  cookieStore.set(NOTIFICATIONS_COOKIE, enabled ? 'off' : 'on', {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
  })

  revalidatePath('/')
}

