args.newString:
import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications-enabled')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'ON' : 'OFF'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? 'Turn off notifications' : 'Turn on notifications'}
        </button>
      </form>
    </main>
  )
}

